            }
        }
        return reservations;
    }

    private static Reservation mapRowToReservation(ResultSet rs) throws SQLException {
        Double refund = rs.getObject("refund") != null ? rs.getDouble("refund") : null;
        return new Reservation(
            rs.getLong("id"),
