package com.pousadamareaalta.util;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class Formatter {
    private static final DateTimeFormatter BR_DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    private static final DateTimeFormatter ISO_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");

    public static String formatDateBR(LocalDate date) {
        return date.format(BR_DATE_FORMAT);
    }

    public static String formatDateISO(LocalDate date) {
        return date.format(ISO_DATE_FORMAT);
    }

    public static String formatCurrency(double value) {
        return String.format("R$ %.2f", value).replace(".", ",");
    }

    public static String formatCurrencyCSV(double value) {
        return String.format("%.2f", value);
    }

    public static String formatCpf(String cpf) {
        if (cpf == null || cpf.length() != 11) {
            return cpf;
        }
        return String.format("%s.%s.%s-%s",
            cpf.substring(0, 3),
            cpf.substring(3, 6),
            cpf.substring(6, 9),
            cpf.substring(9, 11)
        );
    }
}

package com.pousadamareaalta.service;

import com.pousadamareaalta.database.*;
import com.pousadamareaalta.domain.*;
import com.pousadamareaalta.util.*;
import java.sql.SQLException;
import java.util.*;

public class MessageService {
    public static void sendConfirmationEmail(Reservation reservation, Room room) throws SQLException {
        String receiptText = generateReceiptText(reservation, room);

        String emailBody = String.format("""
            Olá, %s!

            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:

            %s

            A entrada é a partir das 14h, e a saída, até as 12h.
            Até breve!
            """,
            reservation.guestName(),
            receiptText
        );

        MessageRepository.create(
            "EMAIL",
            reservation.guestEmail(),
            "Reserva confirmada - Pousada Maré Alta",
            emailBody
        );
    }

    public static String generateReceiptText(Reservation reservation, Room room) {
        int nights = reservation.nights();
        String nightsLabel = nights == 1 ? "1 diária" : nights + " diárias";

        StringBuilder receipt = new StringBuilder();
        receipt.append("Comprovante de reserva nº ").append(reservation.id()).append("\n");
        receipt.append("Hóspede: ").append(reservation.guestName());
        receipt.append(" (CPF ").append(Formatter.formatCpf(reservation.guestCpf())).append(")\n");
        receipt.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
        receipt.append("Entrada: ").append(Formatter.formatDateBR(reservation.checkIn()));
        receipt.append(" | Saída: ").append(Formatter.formatDateBR(reservation.checkOut()));
        receipt.append(" | ").append(nightsLabel).append("\n");
        receipt.append("Diárias: ").append(Formatter.formatCurrency(reservation.subtotal())).append("\n");

        if (reservation.discount() > 0) {
            receipt.append("Desconto: ").append(Formatter.formatCurrency(reservation.discount())).append("\n");
        }

        receipt.append("Total: ").append(Formatter.formatCurrency(reservation.total()));

        return receipt.toString();
    }

    public static List<Message> getAllMessages() throws SQLException {
        return MessageRepository.findAll();
    }
}

