package com.pousadamareaalta.service.report;

import com.pousadamareaalta.database.*;
import com.pousadamareaalta.domain.*;
import com.pousadamareaalta.util.FormatterUtil;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.*;

public class OccupancyReport implements ReportGenerator {
    private final LocalDate date;

    public OccupancyReport(LocalDate date) {
        this.date = date;
    }

    @Override
    public String generate() throws SQLException {
        List<Reservation> reservations = ReservationRepository.findByDateOccupancy(date);
        List<Room> allRooms = RoomRepository.findAll();

        StringBuilder csv = new StringBuilder();
        csv.append("Pousada Maré Alta,occupancy,").append(Formatter.formatDateISO(date)).append("\n");
        csv.append("room,type,reservation,check_in,check_out\n");

        for (Room room : allRooms) {
            Optional<Reservation> reservation = reservations.stream()
                .filter(r -> r.roomNumber() == room.number())
                .findFirst();

            if (reservation.isPresent()) {
                Reservation res = reservation.get();
                csv.append(res.roomNumber()).append(",");
                csv.append(room.type()).append(",");
                csv.append(res.id()).append(",");
                csv.append(Formatter.formatDateISO(res.checkIn())).append(",");
                csv.append(Formatter.formatDateISO(res.checkOut())).append("\n");
            }
        }

        long occupiedCount = reservations.size();
        long totalCount = allRooms.size();
        csv.append("total,").append(occupiedCount).append("/").append(totalCount);

        return csv.toString();
    }

    @Override
    public String getReportName() {
        return "occupancy";
    }
}

package com.pousadamareaalta.service.report;

import com.pousadamareaalta.database.*;
import com.pousadamareaalta.domain.*;
import com.pousadamareaalta.util.*;
import java.sql.SQLException;
import java.time.YearMonth;
import java.util.*;

public class RevenueReport implements ReportGenerator {
    private final YearMonth month;

    public RevenueReport(YearMonth month) {
        this.month = month;
    }

    @Override
    public String generate() throws SQLException {
        List<Reservation> reservations = ReservationRepository.findByMonthStarting(month.getYear(), month.getMonthValue());

        StringBuilder csv = new StringBuilder();
        csv.append("Pousada Maré Alta,revenue,").append(month.getYear()).append("-");
        if (month.getMonthValue() < 10) csv.append("0");
        csv.append(month.getMonthValue()).append("\n");

        csv.append("reservation,room,check_in,check_out,status,amount\n");

        double totalAmount = 0.0;
        for (Reservation res : reservations) {
            double amount = res.amountPaid();
            if (res.refund() != null) {
                amount -= res.refund();
            }

            csv.append(res.id()).append(",");
            csv.append(res.roomNumber()).append(",");
            csv.append(Formatter.formatDateISO(res.checkIn())).append(",");
            csv.append(Formatter.formatDateISO(res.checkOut())).append(",");
            csv.append(res.status()).append(",");
            csv.append(Formatter.formatCurrencyCSV(amount)).append("\n");

            totalAmount += amount;
        }

        csv.append("total,,,,").append(Formatter.formatCurrencyCSV(totalAmount));

        return csv.toString();
    }

    @Override
    public String getReportName() {
        return "revenue";
    }
}

