package com.pousadamareaalta.service;

import com.pousadamareaalta.database.*;
import com.pousadamareaalta.domain.*;
import com.pousadamareaalta.util.*;
import java.sql.SQLException;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;

public class ReservationService {
    public static Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
                                    LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan)
            throws SQLException {

        Optional<Room> room = RoomRepository.findByNumber(roomNumber);
        if (room.isEmpty()) {
            throw new IllegalArgumentException("ROOM_NOT_FOUND");
        }

        if (guests < 1) {
            throw new IllegalArgumentException("INVALID_REQUEST");
        }

        if (guests > room.get().capacity()) {
            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
        }

        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
            throw new IllegalArgumentException("INVALID_REQUEST");
        }

        if (!ReservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
        }

        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
        double subtotal = PriceCalculator.calculateSubtotal(room.get().nightlyRate(), checkIn, checkOut);
        double discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
        double total = PriceCalculator.calculateTotal(subtotal, discount);

        Reservation reservation = new Reservation(
            0,
            roomNumber,
            guestName,
            guestEmail,
            guestCpf,
            checkIn,
            checkOut,
            guests,
            ratePlan,
            nights,
            subtotal,
            discount,
            total,
            "PENDING",
            0.0,
            null
        );

        long id = ReservationRepository.create(reservation);
        return reservation.withAmountPaid(0.0);
    }

    public static Reservation getById(long id) throws SQLException {
        Optional<Reservation> reservation = ReservationRepository.findById(id);
        if (reservation.isEmpty()) {
            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
        }
        return reservation.get();
    }

    public static Reservation confirm(long id) throws SQLException {
        Reservation reservation = getById(id);

        if (!"PENDING".equals(reservation.status())) {
            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
        }

        ReservationRepository.updateStatus(id, "CONFIRMED");
        ReservationRepository.updateAmountPaid(id, reservation.total());

        return reservation.withStatus("CONFIRMED").withAmountPaid(reservation.total());
    }

    public static Reservation checkIn(long id) throws SQLException {
        Reservation reservation = getById(id);

        if (!"CONFIRMED".equals(reservation.status())) {
            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
        }

        ReservationRepository.updateStatus(id, "CHECKED_IN");
        return reservation.withStatus("CHECKED_IN");
    }

    public static Reservation checkOut(long id) throws SQLException {
        Reservation reservation = getById(id);

        if (!"CHECKED_IN".equals(reservation.status())) {
            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
        }

        ReservationRepository.updateStatus(id, "CHECKED_OUT");
        return reservation.withStatus("CHECKED_OUT");
    }

    public static Reservation cancel(long id) throws SQLException {
        Reservation reservation = getById(id);

        if (!"PENDING".equals(reservation.status()) && !"CONFIRMED".equals(reservation.status())) {
            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
        }

        Double refund = null;
        if ("CONFIRMED".equals(reservation.status())) {
            if ("STANDARD".equals(reservation.ratePlan())) {
                refund = reservation.amountPaid();
            } else {
                refund = 0.0;
            }
        }

        ReservationRepository.updateStatus(id, "CANCELLED");
        if (refund != null) {
            ReservationRepository.updateRefund(id, refund);
        }

        return reservation.withStatus("CANCELLED").withRefund(refund);
    }
}

package com.pousadamareaalta;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.pousadamareaalta.database.*;
import com.pousadamareaalta.domain.*;
import com.pousadamareaalta.service.*;
import com.pousadamareaalta.service.report.*;
import com.pousadamareaalta.util.*;
import io.javalin.Javalin;
import io.javalin.json.JsonMapper;
import java.lang.reflect.Type;
import java.sql.SQLException;
import java.time.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws SQLException {
        String dbUrl = System.getenv("DB_URL");
        String dbUser = System.getenv("DB_USER");
        String dbPassword = System.getenv("DB_PASSWORD");
        String portStr = System.getenv("PORT");
        int port = portStr != null ? Integer.parseInt(portStr) : 7070;

        Database.initialize(dbUrl, dbUser, dbPassword);

        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

        Javalin app = Javalin.create(config -> {
            config.jsonMapper(new JsonMapper() {
                @Override
                public String toJsonString(Object obj, Type type) {
                    try {
                        return mapper.writeValueAsString(obj);
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                }

                @Override
                public Object fromJsonString(String json, Type targetType) {
                    try {
                        return mapper.readValue(json, mapper.constructType(targetType));
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                }
            });
        });

        app.get("/rooms", ctx -> {
            try {
                List<Room> rooms = RoomRepository.findAll();
                ctx.json(rooms);
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.post("/reservations", ctx -> {
            try {
                Map<String, Object> body = ctx.bodyAsClass(Map.class);

                int roomNumber = ((Number) body.get("roomNumber")).intValue();
                String guestName = (String) body.get("guestName");
                String guestEmail = (String) body.get("guestEmail");
                String guestCpf = (String) body.get("guestCpf");
                LocalDate checkIn = LocalDate.parse((String) body.get("checkIn"));
                LocalDate checkOut = LocalDate.parse((String) body.get("checkOut"));
                int guests = ((Number) body.get("guests")).intValue();
                String ratePlan = (String) body.get("ratePlan");

                if (checkIn == null || checkOut == null) {
                    ctx.status(400);
                    ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
                    return;
                }

                Reservation reservation = ReservationService.create(
                    roomNumber, guestName, guestEmail, guestCpf,
                    checkIn, checkOut, guests, ratePlan
                );

                long id = ReservationRepository.create(reservation);
                Reservation created = reservation;
                Optional<Reservation> opt = ReservationRepository.findById(id);
                if (opt.isPresent()) {
                    created = opt.get();
                }

                ctx.status(201);
                ctx.json(created);
            } catch (IllegalArgumentException e) {
                String errorCode = e.getMessage();
                if ("ROOM_NOT_FOUND".equals(errorCode)) {
                    ctx.status(404);
                } else if ("CAPACITY_EXCEEDED".equals(errorCode)) {
                    ctx.status(422);
                } else if ("ROOM_UNAVAILABLE".equals(errorCode)) {
                    ctx.status(409);
                } else {
                    ctx.status(400);
                }
                ctx.json(Map.of("error", errorCode, "message", errorCode));
            } catch (Exception e) {
                ctx.status(400);
                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
            }
        });

        app.get("/reservations/{id}", ctx -> {
            try {
                long id = Long.parseLong(ctx.pathParam("id"));
                Reservation reservation = ReservationService.getById(id);
                ctx.json(reservation);
            } catch (IllegalArgumentException e) {
                ctx.status(404);
                ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.post("/reservations/{id}/confirmation", ctx -> {
            try {
                long id = Long.parseLong(ctx.pathParam("id"));
                Reservation reservation = ReservationService.confirm(id);

                Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
                if (room.isPresent()) {
                    MessageService.sendConfirmationEmail(reservation, room.get());
                }

                ctx.json(reservation);
            } catch (IllegalArgumentException e) {
                String errorCode = e.getMessage();
                if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
                    ctx.status(404);
                } else {
                    ctx.status(409);
                }
                ctx.json(Map.of("error", errorCode, "message", errorCode));
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.post("/reservations/{id}/cancellation", ctx -> {
            try {
                long id = Long.parseLong(ctx.pathParam("id"));
                Reservation reservation = ReservationService.cancel(id);
                ctx.json(reservation);
            } catch (IllegalArgumentException e) {
                String errorCode = e.getMessage();
                if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
                    ctx.status(404);
                } else {
                    ctx.status(409);
                }
                ctx.json(Map.of("error", errorCode, "message", errorCode));
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.post("/reservations/{id}/check-in", ctx -> {
            try {
                long id = Long.parseLong(ctx.pathParam("id"));
                Reservation reservation = ReservationService.checkIn(id);
                ctx.json(reservation);
            } catch (IllegalArgumentException e) {
                String errorCode = e.getMessage();
                if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
                    ctx.status(404);
                } else {
                    ctx.status(409);
                }
                ctx.json(Map.of("error", errorCode, "message", errorCode));
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.post("/reservations/{id}/check-out", ctx -> {
            try {
                long id = Long.parseLong(ctx.pathParam("id"));
                Reservation reservation = ReservationService.checkOut(id);

                Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
                if (room.isEmpty()) {
                    ctx.status(500);
                    ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
                    return;
                }

                Receipt receipt = new Receipt(
                    "Comprovante de reserva",
                    reservation.id(),
                    reservation.guestName(),
                    reservation.guestCpf(),
                    reservation.roomNumber(),
                    room.get().type(),
                    reservation.checkIn(),
                    reservation.checkOut(),
                    reservation.nights(),
                    reservation.subtotal(),
                    reservation.discount(),
                    reservation.total()
                );

                ctx.json(receipt);
            } catch (IllegalArgumentException e) {
                String errorCode = e.getMessage();
                if ("RESERVATION_NOT_FOUND".equals(errorCode)) {
                    ctx.status(404);
                } else {
                    ctx.status(409);
                }
                ctx.json(Map.of("error", errorCode, "message", errorCode));
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.get("/reservations/{id}/document", ctx -> {
            try {
                long id = Long.parseLong(ctx.pathParam("id"));
                Reservation reservation = ReservationService.getById(id);

                if (!"CONFIRMED".equals(reservation.status()) &&
                    !"CHECKED_IN".equals(reservation.status()) &&
                    !"CHECKED_OUT".equals(reservation.status())) {
                    ctx.status(409);
                    ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Second copy only available for paid reservations"));
                    return;
                }

                Optional<Room> room = RoomRepository.findByNumber(reservation.roomNumber());
                if (room.isEmpty()) {
                    ctx.status(500);
                    ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
                    return;
                }

                Receipt receipt = new Receipt(
                    "Comprovante de reserva",
                    reservation.id(),
                    reservation.guestName(),
                    reservation.guestCpf(),
                    reservation.roomNumber(),
                    room.get().type(),
                    reservation.checkIn(),
                    reservation.checkOut(),
                    reservation.nights(),
                    reservation.subtotal(),
                    reservation.discount(),
                    reservation.total()
                );

                ctx.json(receipt);
            } catch (IllegalArgumentException e) {
                ctx.status(404);
                ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.get("/messages", ctx -> {
            try {
                List<Message> messages = MessageService.getAllMessages();
                ctx.json(messages);
            } catch (SQLException e) {
                ctx.status(500);
                ctx.json(Map.of("error", "DATABASE_ERROR", "message", e.getMessage()));
            }
        });

        app.get("/reports/occupancy", ctx -> {
            try {
                String dateStr = ctx.queryParam("date");
                LocalDate date = LocalDate.parse(dateStr);

                ReportGenerator report = new OccupancyReport(date);
                String csv = report.generate();

                ctx.contentType("text/csv; charset=utf-8");
                ctx.result(csv);
            } catch (Exception e) {
                ctx.status(400);
                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
            }
        });

        app.get("/reports/revenue", ctx -> {
            try {
                String monthStr = ctx.queryParam("month");
                YearMonth month = YearMonth.parse(monthStr);

                ReportGenerator report = new RevenueReport(month);
                String csv = report.generate();

                ctx.contentType("text/csv; charset=utf-8");
                ctx.result(csv);
            } catch (Exception e) {
                ctx.status(400);
                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
            }
        });

        app.get("/reports/tourism-tax", ctx -> {
            try {
                String monthStr = ctx.queryParam("month");
                YearMonth month = YearMonth.parse(monthStr);

                ReportGenerator report = new TourismTaxReport(month);
                String csv = report.generate();

                ctx.contentType("text/csv; charset=utf-8");
                ctx.result(csv);
            } catch (Exception e) {
                ctx.status(400);
                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
            }
        });

        app.get("/reports/rate-plans", ctx -> {
            try {
                String monthStr = ctx.queryParam("month");
                YearMonth month = YearMonth.parse(monthStr);

                ReportGenerator report = new RatePlansReport(month);
                String csv = report.generate();

                ctx.contentType("text/csv; charset=utf-8");
                ctx.result(csv);
            } catch (Exception e) {
                ctx.status(400);
                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
            }
        });

        app.start(port);
    }
}

